    b+='<path d="M60 60 Q40 200 70 330 Q90 430 150 520" fill="none" stroke="#555" stroke-width="6"/>'
    b+='<path d="M60 60 Q40 200 70 330 Q90 430 150 520" fill="none" stroke="#bbb" stroke-width="2"/>'
    b+='<path d="M380 160 Q430 260 400 330 Q350 340 330 260Z" fill="#cde" stroke="#555" stroke-width="2"/>'
    b+='<ellipse cx="300" cy="440" rx="85" ry="60" fill="#eee" stroke="#555" stroke-dasharray="2 4"/>'
    b+='<path d="M200 560 Q300 520 420 540" fill="none" stroke="#555" stroke-width="3"/>'
    b+='<polyline points="95,150 110,240 130,330" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="8 4"/>'
    b+='<path d="M110 340 L170 420" fill="none" stroke="#111" stroke-width="2"/><path d="M110 330 L190 360" fill="none" stroke="#111" stroke-width="2"/>'
    for x,y,t in labels: b+=T(x,y,t,12,'middle',700)
    b+='<line x1="260" y1="70" x2="360" y2="70" stroke="#111" stroke-width="2"/>'+T(310,88,'میل',11,'middle',700)
    return svg(w,h,cap,b)
